def nested_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Nested groups are not balanced (some parentheses not closed), each group contains less parentheses then it's parent.
    Ignore any spaces in the input string.
    >>> nested_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    result = []
    parent = []
    for paren in paren_string:
        if paren == '(':
            parent.append(paren)
        else:
            if len(parent) == 1:
                result.append(paren)
            else:
                parent.pop()
    return result


