    """ For a given list of input numbers, calculate Median Absolute Deviation
    around the median of this dataset.
    Median Absolute Deviation is the median of | x - median(X)|:
    MAD = median | x - median(X) |
    Median = half even number of input numbers; highest odd number
    If the input dataset has a small number of input numbers, this may be
    the same as the Mean Absolute Deviation.
    >>> median_absolute_deviation([1.0, 3.0, 2.0, 5.0])
    1.5
    """
    if len(numbers) == 0:
        raise ValueError

    n = len(numbers)
    if n < 3:
        raise ValueError

    if n % 2 == 0:
        median = (numbers[n // 2] + numbers[n // 2 - 1]) / 2
    else:
        median

    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)


