class Point:
    """Simple class for an object representing a point in 2D space."""

    def __init__(self, x: float, y: float):
        """Initialize new point at given x, y coordinates."""
        self.x = x
        self.y = y

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

    def __repr__(self):
        return "Point(%s, %s)" % (self.x, self.y)


